import { readFileSync, writeFileSync } from 'node:fs';
const root = 'node_modules/leaflet/';
const license = readFileSync(root + 'LICENSE', 'utf8');
const js = readFileSync(root + 'dist/leaflet.js', 'utf8').replace(
  /\/\/# sourceMappingURL=.*$/m,
  '',
);
const css = readFileSync(root + 'dist/leaflet.css', 'utf8');
const output =
  '// Generated by scripts/bundle-map.mjs. Leaflet 1.9.4, BSD-2-Clause.\n' +
  'export const leafletJS = ' +
  JSON.stringify(js) +
  ';\nexport const leafletCSS = ' +
  JSON.stringify(css) +
  ';\n';
writeFileSync('src/features/map/leafletSource.js', output);
writeFileSync('src/features/map/LEAFLET-LICENSE.txt', license);
